     "Indikation: ischemisk stroke ≤4,5 timmar från symtomdebut/senast kända symtomfria tid, ålder ≥16 år; 4,5–9 timmar eller wake-up stroke vid räddningsbar vävnad på DT-perfusion/MR DWI-FLAIR (ännu ej etablerat)",
     "Absoluta kontraindikationer: blodtryck ≥185/110 trots behandling, misstänkt annan diagnos (ICH, SAB, tumör, aortadissektion), infarkt >1/3 av kärlterritoriet, tidigare spontan ICH, septisk embolisering, icke-komprimerbar blödning, pågående antikoagulantia (warfarin med PK-INR >1,7; NOAK senaste 48 h)",
     "Relativa kontraindikationer: P-glukos <3, krampanfall, inga kvarvarande symtom, GCS <12, stroke/intrakraniell operation/svårt trauma <6 v, GI-/urinvägsblödning 3 v, LP 7 d, HLR 10 d, större operation 2 v, tpk <100",
