     "Gånghastighet som enstaka mått. Exempel: hos ≥85-åringar styrde gånghastigheten sambandet mellan blodtryck och överlevnad (>0,5 m/s: högt blodtryck gav sämre överlevnad; <0,5 m/s eller icke-gångare: inget säkert samband)",
