     "Orsaker: primärdegenerativa ca 60 % (Alzheimer, frontotemporal, Lewy body, Parkinsondemens), vaskulär kognitiv sjukdom ca 30 %, övriga (tumör, blödning, hydrocefalus, alkohol, infektioner)",
     "Svårighetsgrad: subjektiva besvär; mild kognitiv sjukdom (MCI: objektiv nedsättning utan ADL-påverkan, ca 3× risk för demens, ca 50 % utvecklar demens på 4 år); mild demens (instrumentell ADL påverkad), medelsvår (personlig ADL), svår (helt beroende)",
