    "k": "",
    "d": "CAM: 1) akut debut och fluktuerande förlopp, 2) ouppmärksamhet, 3) desorganiserat tänkande, 4) förändrad vakenhetsgrad. Förvirring om 1 + 2 och antingen 3 eller 4. DSM-5: A störning i uppmärksamhet och medvetenhet, B snabb utveckling och fluktuation, C ytterligare kognitiv störning, D förklaras inte bättre av existerande kognitiv störning, E direkt följd av medicinskt tillstånd. Orientering: tid försvinner först, sedan plats, sist person. Räkna månaderna baklänges (klarar fram till juli = OK; sensitivitet 83 %, specificitet 91 %). Anhörig-/vårdaranamnes är ofta första ledtråden. Leta orsak: stroke, icke-konvulsivt status epileptikus, läkemedelsbiverkan, droger, urinstämma, förstoppning, sömnbrist, alkoholabstinens, Wernickes encefalopati (tiaminbrist). Sjuksköterska: bladderscan, glukos, blodtryck, saturation, andningsfrekvens. Läkare: läkemedelslista, brett blodprov.",
