    "b": "Eliminera utlösare (läkemedel, infektion), 10 % glukosinfusion 2–3 L/dygn, vid svårare fall hemarginat (Normosang 3 mg/kg/dag i 3–4 dagar), adekvat näring. Symtomatiskt: smärta opiater; illamående klorpromazin/ondansetron/haloperidol; förstoppning senna/laktulos; hyponatremi substitution; konfusion/psykos klorpromazin; epilepsi magnesiumsulfat/klonazepam; hypertoni atenolol/labetalol. Cykliska attacker: GnRH-agonister; levertransplantation vid svår AIP; läkemedelsdatabas www.drugs-porphyria.org.",
