     "Orsak: natriumförlust (Addison, kräkningar/diarré, njur-/hjärtsvikt) eller vattenöverskott (SIADH, polydipsi). Vanligaste orsaker vid kronisk hyponatremi hos vuxna: tiaziddiuretika, SIADH (läkemedelsutlöst), alkohol",
