    "b": "Svåra symtom (kramper/koma): hyperton NaCl 3 % (2 ml/kg, max 110 ml, upprepas max 2 ggr; höjer P-Na ca 2 mmol/L per dos) på IVA tills symtomen viker (≈2–6 mmol/L); därefter långsamt. Korrektionstak ≤8–12 mmol/L per 24 h och 18 mmol/L per 48 h – risk för osmotiskt demyeliniseringssyndrom (tremor, dysartri, dysfagi, spastisk tetrapares, locked-in). Måttliga symtom: isoton NaCl vid U-Na <20, vätskerestriktion (<1000 ml) vid utspädning, furosemid vid övervätskning; avbryt utlösande läkemedel (tiazid, SSRI). Låt ingen dö i kortisolbrist (100 mg Solu-Cortef).",
