     "Induktion/remission med steroider (budesonid), tiopuriner (azatioprin), metotrexat, anti-TNF, vedolizumab, ustekinumab, risankizumab, upadacitinib (UC+CD)",
     "Kirurgi vid stenoser och fistlar; mål att ta bort så lite tarm som möjligt. Samma kolorektalcancerövervakning som UC vid Crohnkolit >1/3"
