    "fk": "Anemiutredning inom gastroenterologin: mikrocytär anemi/järnbrist, B12- och folatbrist samt blodförlust kan ha gastrointestinal orsak; anemi, järnbrist och positivt F-Hb räknas som larmsymtom.",
