    "k": "",
    "d": "Mikrocytär anemi (MCV <80): järnbrist (vanligast), thalassemi, ibland kronisk sjukdom; kontrollera järnstatus (ferritin, transferrin), F-Hb, retikulocyter; ferritin kan vara falskt högt vid inflammation, lösligt transferrinreceptor kan skilja. Vid uttalad järnbristanemi: gastrointestinal utredning för att leta orsak, eftersom tumörer kan blöda. Makrocytär anemi: alkoholanamnes, B12, folat, hemolysprover, vid oklarhet benmärg",
