    "b": "Reperfusion: primär PCI om patienten kan vara på PCI-lab inom 120 min (<90 min från kontakt), annars trombolys (”drip-n-ship” i Västerbotten); efter lyckad trombolys angio efter 2–24 h; misslyckad trombolys rescue-PCI. ASA 300–500 mg; primär PCI: laddning ticagrelor 180 mg / prasugrel 60 mg / klopidogrel 600 mg + heparin 5000 IE; trombolys: klopidogrel 300 mg, fondaparinux (Arixtra) 2,5 mg s.c., Metalyse; i.v. betablockad om stabil, nitro och morfin vid behov, syrgas om POX <90 %. Sekundärprevention: rökstopp, kost, alkohol, vikt, fysisk aktivitet, DAPT 12 mån, statin, ACEi/ARB, betablockad, MRA vid svikt, PPI vid hög blödningsrisk, SGLT2-hämmare/GLP-1 vid diabetes",
