    "d": "Skatta njurfunktion med kreatinin- eller cystatin C-baserad eGFR; cystatin C (CAPA) vid avvikande muskelmassa (felkällor: hyperlipemi, tyreoideadysfunktion, kortison, graviditet, malignitet). eGFR beräknas relativt (per 1,73 m²); absolut eGFR (ml/min) kräver vikt och längd och ska användas vid läkemedelsdosering. www.egfr.se; LM-rev; CKD-EPI. Shrunken pore syndrome = selektiv glomerulär hypofiltration",
    "b": "Använd absolut eGFR vid dosering",
    "m": ""
