    "b": "Pulverinhalator (DPI): drivs av patientens inandning, kräver djup och kraftfull inandning (inspiratoriskt flöde >30 l/min); sitt upp, andas ut helt men aldrig i inhalatorn (fuktkänslig), inhalera snabbt från början så länge det går, håll andan. Kontrollera dosräknare. Barn från 5–6 år. Spray (MDI): ska ges med spacer; skaka, spraya en puff i taget, andas ut, inhalera lugnt, håll andan; spraya i luften första gången och efter 2 veckors uppehåll. Spacer diskas varje vecka och byts varje år; kan användas i alla åldrar (med mask vid behov). Algoritm: kan patienten inte göra medveten/styrd inandning eller har inspiratoriskt flöde <30 l/min → spray + spacer (± mask); koordinationsproblem → spacer. Äldre med sämre allmäntillstånd kan ha svårt med pulverinhalator; spray + spacer fungerar för alla åldrar. Be patienten visa hur hen inhalerar; kontrollera teknik och följsamhet innan behandlingen ändras och vid varje återbesök. Gå igenom: vet patienten syftet, hur man ser att den är tom, laddar dos, andas djupt och kraftfullt, håller andan, sköljer munnen efter ICS; skriftlig behandlingsplan",
