    "v": [
     "Epidemiologi: ca 4 200 nya fall/år i Sverige, fjärde vanligaste cancerformen, flest cancerdödsfall (ca 3 600/år); medianålder ca 70 år; 5-årsöverlevnad ca 17 % (stadium I 65 %, II 40 %, III 20 %, IV 5 %); 85 % av fallen rökare/f.d. rökare, 15 % aldrig-rökare",
     "Andra orsaker: passiv rökning, asbest, radon (särskilt vid samtidig rökning), luftföroreningar",
     "Lokalsymtom: hosta, hemoptys, dyspné, upprepade infektioner. B-symtom: feber, viktnedgång, nattsvettningar, trötthet. Kan vara symtomfri (bifynd)",
     "Lokal inväxt: v. cava superior-syndrom (svullnad i halsen, andnöd), n. phrenicus (diafragmapares), n. recurrens (stämbandspares, heshet), Pancoast-tumör i plexus brachialis (armsmärta, Horners syndrom: ptos, mios, enoftalmus)",
     "Paraneoplastiskt: hyponatremi (SIADH), hyperkalcemi, Lambert-Eatons myastena syndrom"
    ],
    "k": "",
    "d": "Standardiserat vårdförlopp (SVF): misstanke (remiss till bilddiagnostik) vid nytillkomna luftvägssymtom >6 veckor hos rökare/f.d. rökare >40 år, oförklarlig bröst-/skuldersmärta eller blodig hosta. Välgrundad misstanke (remiss till lungenhet; start på SVF): fynd på bilddiagnostik eller metastasfynd som ger misstanke om lungcancer, v. cava-obstruktion, recurrenspares, upprepad blodig hosta utan annan förklaring (även vid normal lungröntgen). Utredning i tre delar: bilddiagnostik (lungröntgen, DT thorax + övre buk, PET-DT, DT/MR hjärna vid mutation/SCLC/stadium III eller symtom), vävnadsprov (transtorakal biopsi, bronkoskopi/EBUS-TBNA, pleuratappning, biopsi av metastas) med histologi och molekylärpatologi, samt funktionsutredning (EKG, spirometri + diffusionskapacitet, performance status, samsjuklighet). Vanliga metastaslokaler: lymfkörtlar, hjärna, skelett, lever, binjurar, lunga. TNM (8:e upplagan) gäller även småcellig lungcancer. WHO performance status 0–4 (0 frisk … 4 sängliggande). Molekylär testning vid icke-småcellig: EGFR, BRAF, KRAS, MET, ERBB2, ALK, ROS1, RET, NTRK och PD-L1",
    "b": "Behandlingen styrs av stadium, tumörtyp, performance status och samsjuklighet. Stadium I: operation (oftast lobektomi, ofta VATS); inoperabla (t.ex. grav KOL): stereotaktisk strålbehandling i kurativt syfte. Stadium II: operation följt av cytostatika/TKI/immunterapi; stadium III: cytostatika + strålbehandling följt av ev. målriktad behandling eller immunterapi. Stadium IV: aldrig operation; palliativ behandling – målriktad (tablett, vid EGFR/ALK/ROS1/BRAF m.fl.), immunterapi ± cytostatika eller cytostatika. EGFR förekommer hos 10–15 % av adenocarcinom, ALK 3–4 %, ROS1 1–2 % av NSCLC. Småcellig (SCLC): snabbväxande, tidig metastasering, kirurgi sällan till nytta, cytostatikakänslig (70–80 % svarar); standard cytostatika + immunterapi, kompletterande strålbehandling. Övrigt: best supportive care i team, tidig palliativ hemsjukvård. Lungröntgen 6–8 veckor efter pneumoni hos rökare/f.d. rökare >40 år eller vid komplicerad pneumoni; var frikostig med lungröntgen",
