     "Större (>3 cm apikalt eller >2 cm lateralt) eller påverkad patient: pleuradrän (akut vid medtagen patient/risk för försämring; relativt opåverkad utanför kontorstid kan läggas in över natten med 1–2 l syrgas och dräneras dagen efter)",
     "Dränkontroll: ofta aktivt sug i början (10–15 cm H2O); kontrollera insticksställe och subkutant emfysem dagligen och dränagelåda minst 3 ggr/dygn; bubblar det läcker luft; när det slutat bubbla ny lungröntgen, kan stängas, ny röntgen efter ca 12 timmar, därefter dränet avlägsnas",
     "Heimlichventil/kompakt dränage möjligt poliklinisk behandling vid okomplicerad spontan pneumothorax",
