   "card": {
    "fk": "Oförmåga att hålla normala blodgaser i vila: pO2 <8 kPa och/eller pCO2 >6,5 kPa (normalt pO2 10–13,6, pCO2 4,5–6 kPa).",
    "v": [
     "Orsaker: ökad luftvägsobstruktion, luftvägsinfektion, lungemboli, vänsterkammarsvikt, narkotika/sederande läkemedel, multipla revbensfrakturer, okontrollerad syrgastillförsel",
     "Mekanismer: ventilations-perfusionsrubbning, diffusionshinder (fibros, ödem, emfysem), shunt, hypoventilation",
     "Akut försämring av kronisk insufficiens kan vara smygande: dyspné, hosta, trötthet, huvudvärk, förvirring, högersvikt"
    ],
    "k": "",
    "d": "Artärblodgas krävs; tolkning: pH → pCO2 → BE (normalt ±3 mmol/l). Akut respiratorisk acidos: lågt pH, högt pCO2, normalt BE; metabolt kompenserad: normalt pH, högt pCO2, BE förhöjt; metabol acidos: lågt pH, lågt pCO2, lågt BE. Alveolär gasformel: pO2 + 1,25 × pCO2 ≈ 20 (A-a-gradient = 20 − summan); >17 godtagbart hos äldre. Exempel: pH 7,23, pCO2 9,5, BE 2 = akut okompenserad respiratorisk acidos (instabil, ny blodgas efter 30–60 min).",
    "b": "Kontrollerad syrgasterapi (syrgas är ett läkemedel: ordineras av läkare, följs upp kontinuerligt). Normalt/lågt pCO2: mål pO2 >10 kPa och sat >93 %, 2–4 l/min. Förhöjt pCO2 (hypoxisk drive): så lite O2 som möjligt men pO2 >8 kPa; börja ½–1 l/min och kontrollera blodgas ofta; avstå aldrig från syrgas vid hypoxemi – vid försämring NIPPV i första hand. Behandla grundorsaken; följ artärblodgas; ställningstagande till ventilationsunderstöd (intubation kontraindicerat i slutstadiet av kronisk insufficiens). Hypoxigränser: sat 25 %/pO2 2,5 kPa absolut överlevnadsgräns; 70 %/5,0 risk för hypoxiska skador; 80 %/6,0 kan accepteras över natten; 88–90 %/7,5–8,0 målvärde före hemgång.",
    "m": ""
   },
