    "def": "Systematisk undersökning av lungorna: inspektion, (palpation), perkussion och auskultation.",
    "klin": [
     "Inspektion: andningsfrekvens (normal 12–20/min), SpO2 på luft (>95 %), andningsmönster (Cheyne-Stokes vid hjärtsvikt/stroke, Kussmaul vid ketoacidos/uremi), thoraxform (tunnformad vid emfysem, pectus, skolios), accessoriska muskler, indragningar",
     "Palpation: thoraxexpansion (normalt symmetrisk 3–5 cm), trakealposition, taktil fremitus (ökad vid konsolidering, minskad vid pleuravätska/pneumothorax/emfysem)",
     "Perkussion: sonor (normal), hypersonor (emfysem, pneumothorax, hyperinflation), dämpad (vätska, konsolidering, tumör)",
     "Auskultation: tidalandning först, apex→bas, fram→bak→sidor, jämför; sedan forcerad exspiration. Normalt vesikulärt; bronkiellt vid konsolidering; försvagat vid effusion/pneumothorax",
     "Biljud: fina rassel/krepitationer (fibros, tidigt ödem), medelgrova (ödem, pneumoni), grova (sekret), pleuralt gnidningsljud, ronki (exspiratoriska = bronkobstruktion, inspiratoriska = övre luftvägshinder, monofona = fokal, polyfona = diffus)",
     "Konsolidering: bronkofoni, egofoni (E blir A), viskad röst hörs tydligt",
     "Mönster: pleuravätska – försvagat + dämpat; pneumothorax – försvagat + hypersonort; konsolidering – bronkiellt + rassel + dämpat; emfysem – försvagat + hypersonort; astma/KOL-exacerbation – exspiratoriska ronki"
    ],
