     "Exakt GFR: iohexolclearance, Cr-EDTA-clearance. Exempel (kvinna 82 år, 48 kg, krea 98): CrCl 29, MDRD 50, CKD-EPI 46 ml/min (relativ) – olika formler ger olika stadium",
     "Urin: U-sticka (proteinuri, hematuri – glomerulär skada eller urologisk hematuri), U-sediment (glomerulära erytrocyter, cylindrar), U-albumin/kreatinin-kvot (glomerulär skada), protein/HC-kvot (tubulär proteinuri)",
     "Stadieindelning CKD: G1 >90, G2 60–89, G3a 45–59, G3b 30–44, G4 15–29, G5 <15 ml/min; albuminuri A1/A2/A3 (se Proteinuri); risk för progress och kardiovaskulär sjuklighet ökar från låg-normal (grön) till hög (röd)",
