     "Sekundära orsaker: kroniska infektioner (hepatit C/B, endokardit, shuntnefrit, svamp, parasiter), autoimmuna sjukdomar (SLE, RA, MCTD), monoklonala gammopatier (MGUS/MGRS, lymfom, KLL, myelom)"
