   "card": {
    "fk": "Peritonealdialys (PD): dialys genom bukhinnan via kateter i fria bukhålan, som ger rening, elektrolytkorrektion och vätskeborttagning.",
    "v": [
     "Modern PD från 1960-talet (Tenckhoff); glukos i dialysvätskan drar vätska",
     "CAPD: patienten byter vätska 4–5 gånger/dag; APD: maskin-PD",
     "Komplikationer: peritonit (intraperitoneal antibiotika), exit site-infektion, hyperglykemi → viktuppgång/diabetes, förlust av ultrafiltrationskapacitet"
    ],
    "k": "",
    "d": "",
    "b": "Fördelar vs HD: mer frihet, hemma, mer fysiologisk vätskebalans, bra vid hjärtsvikt; sämre utan restfunktion. Olämpligt vid tidigare omfattande bukoperationer, kraftig övervikt, dålig hygien, svårigheter att lära sig (assisterad PD kan övervägas), avsaknad av restfunktion, utrymmesproblem hemma.",
    "m": ""
   },
   "km": [
    "njur:0",
    "njur:3"
   ]
