     "Surprise question: ”Skulle du bli förvånad om patienten dog inom de närmaste 6–12 månaderna?”",
     "Vilar >50 % av vaken tid (WHO performance status), viktförlust >10 % senaste halvåret, ≥2 akuta inläggningar inom 6 månader, ihållande symtom i vila trots optimal terapi (t.ex. KOL stadium IV, hjärtsvikt NYHA IV)",
     "Sista dygnen: sängliggande, äter och dricker inte, grumlat medvetande, trådfin snabb puls, marmorerad perifer kyla, minskad urinproduktion, oregelbunden andning, rosslighet, vit spetsig näsa",
