     "S-paracetamol 4 h efter intag (nomogram: 4 h 1000 µmol/L, 6 h 700, 9 h 450, 15 h 150; 75 % av nivån vid riskgrupp); >24 h: paracetamol, PK-INR, leverstatus, laktat, blodgas – fria bara om allt normalt och patienten symtomfri"
